export const getCreateEnvironmentUrl = (projectId: string,) => {




  return `/v1/instance/projects/${projectId}/environments`
}

/**
 * Adds the development or production environment a project lacks, with its first signing keys. A project holds one environment of each kind: a second one is `resource.conflict`. Recorded in the instance audit log. Takes a dashboard session or the instance admin token. A deployment without `TULA_ADMIN_TOKEN` answers 404.
 * @summary Add an environment to a project
 */
export const createEnvironment = async (projectId: string,
    createEnvironmentRequest: CreateEnvironmentRequest, options?: Parameters<typeof dashboardFetch>[1]): Promise<Environment> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return dashboardFetch<Environment>(getCreateEnvironmentUrl(projectId),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(createEnvironmentRequest)
  }
);}





