export const getListInstanceAuditLogsUrl = (params?: ListInstanceAuditLogsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/v1/instance/audit-logs?${stringifiedParams}` : `/v1/instance/audit-logs`
}

/**
 * What the deployment’s operator did outside any one environment, newest first: dashboard sign-ins (and failed ones), sign-outs, and every workspace, project and environment created or renamed. The actor is `instance_admin`; its id is the dashboard session’s, or `null` when the admin token itself was used. Filter by `action`, `actorId`, `targetId` and time (`from` inclusive, `to` exclusive). What was done inside an environment is in that environment’s own audit log (`GET /v1/admin/audit-logs`). Takes a dashboard session or the instance admin token. A deployment without `TULA_ADMIN_TOKEN` answers 404.
 * @summary List the instance audit log
 */
export const listInstanceAuditLogs = async (params?: ListInstanceAuditLogsParams, options?: Parameters<typeof dashboardFetch>[1]): Promise<InstanceAuditLogList> => {

  return dashboardFetch<InstanceAuditLogList>(getListInstanceAuditLogsUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





